style.css:
@-moz-document domain("pinterest.com") {
/* ==========================================================================
       1. CORE INITIALIZATION & BACKGROUNDS
       ========================================================================== */
    :root {
        --pinterest-main-bg: url("https://i.pinimg.com/736x/43/d2/b7/43d2b7b6102a66d5285cdd34b88bff11.jpg");
        --pinterest-overlay: rgba(255, 238, 240, 0.85);
        --pinterest-pink: #ce67b6;       
        --pinterest-purple: #cda3f6;     
    }

    /* Apply the custom gradient and layout properties globally to Pinterest */
    html, body, #pageContainer, .App {
        background: var(--pinterest-main-bg), linear-gradient(-2deg, #fdd6e9 25%, #f2d1fe 80%) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* ==========================================================================
       2. TYPOGRAPHY (Sofia & ABeeZee)
       ========================================================================== */
    /* Target all standard descriptions, text blocks, and interface labels */
    div, span, p, a, button, input {
        font-family: 'ABeeZee', sans-serif !important;
        font-style: italic !important;
        text-shadow: 0px 0px 2px #FFFFFF !important;
    }

    /* Main pin titles, headers, and board text settings fall back to Sofia layout rules */
    h1, h2, h3, [data-test-id="pinTitle"], .X6a {
        font-family: 'Sofia', cursive !important;
        font-style: italic !important;
        font-weight: normal !important;
        color: #ce67b6 !important;
        text-shadow: 0px 0px 2px #FFFFFF !important;
    }

    /* ==========================================================================
       3. INTERFACE OVERLAYS & TRANSPARENCY
       ========================================================================== */
    /* Strip default white block fields from grid container layers */
    div[data-test-id="grid"], 
    div[data-grid-item="true"],
    [data-test-id="pin-builder"],
    .appContent {
        background: transparent !important;
    }

    /* Turn the main header bar translucent matching your theme header lines */
    div[data-test-id="header"] {
        background: url("https://giphy.com"),
                    linear-gradient(to right, #fcdde4ad, #eedaf9ad) !important;
        border-bottom: 1px solid #ffeef04a !important;
        box-shadow: 0px 4px 0px 1px #fffff85 !important;
        backdrop-filter: blur(5px) !important;
    }

    /* Inject frosted pink overlay containers over pin sheets, menus, and text panels */
    div[data-test-id="closeup-wrapper"],
    div[data-test-id="sheet"],
    div[role="listitem"] > div,
    div[data-test-id="Dropdown"] {
        background-color: var(--pinterest-overlay) !important;
        border: #FFFFFF 1px dotted !important;
        border-radius: 10px !important;
        backdrop-filter: blur(5px) !important;
    }

    /* ==========================================================================
       4. INPUT FIELDS & DECORATIONS
       ========================================================================== */
    /* Custom style tracking rules for the search container */
    div[data-test-id="search-box-input-container"], 
    input[data-test-id="search-box-input"] {
        background: linear-gradient(to right, #ffede2, #fff5db) !important;
        border: 1px solid #FFFFFF !important;
        border-radius: 10px !important;
    }

    /* Round image borders and individual cards precisely */
    img, div[style*="border-radius"] {
        border-radius: 10px !important;
    }

    /* Custom Pinterest Scrollbar settings tracking design constraints */
    ::-webkit-scrollbar {
        width: 10px !important;
    }
    ::-webkit-scrollbar-track {
        background: #ffebee !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #f2d1fe !important;
        border: 1px solid #FFFFFF !important;
        border-radius: 5px !important;
    }
}
